<?php require_once '../config.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=db()->prepare('SELECT id,password_hash FROM admins WHERE email=?');$s->execute([strtolower(trim($_POST['email']??''))]);$a=$s->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=(int)$a['id'];redirect('dashboard.php');}$error='Incorrect admin email or password.';}page_start('Factory owner login');if($error)echo '<div class="alert error">'.e($error).'</div>';?><form method="post" class="form panel"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn">Sign in</button><p>First time? <a href="setup.php">Create the owner account</a></p></form><?php page_end();?>
